'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import type { MenuCategoryNavMode } from '@/shared/types/restaurant-styling';

export interface MenuCategoryNavItem {
  id: string;
  name: string;
}

interface MenuCategoryNavProps {
  categories: MenuCategoryNavItem[];
  mode?: MenuCategoryNavMode;
  inHeader?: boolean;
  visible?: boolean;
}

function getCategoryElementId(categoryId: string): string {
  return `menu-category-${categoryId}`;
}

export function MenuCategoryNav({
  categories,
  mode = 'dock_in_header',
  inHeader = false,
  visible = true,
}: MenuCategoryNavProps) {
  const [activeId, setActiveId] = useState(categories[0]?.id ?? '');
  const navRef = useRef<HTMLElement>(null);

  const scrollToCategory = useCallback((categoryId: string) => {
    const element = document.getElementById(getCategoryElementId(categoryId));
    if (!element) {
      return;
    }

    element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setActiveId(categoryId);
  }, []);

  useEffect(() => {
    if (categories.length === 0) {
      return;
    }

    setActiveId((current) =>
      categories.some((category) => category.id === current)
        ? current
        : (categories[0]?.id ?? ''),
    );
  }, [categories]);

  useEffect(() => {
    if (categories.length === 0) {
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const visibleEntries = entries
          .filter((entry) => entry.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);

        if (visibleEntries.length === 0) {
          return;
        }

        const categoryId = visibleEntries[0].target.id.replace('menu-category-', '');
        setActiveId(categoryId);
      },
      { rootMargin: '-35% 0px -55% 0px', threshold: 0 },
    );

    categories.forEach((category) => {
      const element = document.getElementById(getCategoryElementId(category.id));
      if (element) {
        observer.observe(element);
      }
    });

    return () => observer.disconnect();
  }, [categories]);

  useEffect(() => {
    if (!navRef.current || !activeId) {
      return;
    }

    const activeButton = navRef.current.querySelector(`[data-category-id="${activeId}"]`);
    if (activeButton instanceof HTMLElement) {
      activeButton.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
    }
  }, [activeId]);

  if (categories.length <= 1) {
    return null;
  }

  const isHiddenInHeader = inHeader && !visible;

  return (
    <nav
      ref={navRef}
      className={[
        'restaurant-menu__category-nav',
        inHeader ? 'restaurant-menu__category-nav--in-header' : '',
        mode === 'tabs_underline' ? 'restaurant-menu__category-nav--tabs' : '',
        inHeader && visible ? 'restaurant-menu__category-nav--visible' : '',
        isHiddenInHeader ? 'restaurant-menu__category-nav--hidden' : '',
      ]
        .filter(Boolean)
        .join(' ')}
      aria-label="Навигация по категориям меню"
      aria-hidden={isHiddenInHeader}
    >
      <div className="restaurant-menu__category-nav-inner">
        {categories.map((category) => (
          <button
            key={category.id}
            type="button"
            data-category-id={category.id}
            className={[
              'restaurant-menu__category-nav-btn',
              activeId === category.id ? 'restaurant-menu__category-nav-btn--active' : '',
            ]
              .filter(Boolean)
              .join(' ')}
            onClick={() => scrollToCategory(category.id)}
            tabIndex={isHiddenInHeader ? -1 : 0}
          >
            {category.name}
          </button>
        ))}
      </div>
    </nav>
  );
}
