import type { MenuCategory } from '@/shared/types/menu';
import type { MenuCategoryNavMode } from '@/shared/types/restaurant-styling';

export function getAvailableMenuCategories(categories: MenuCategory[]): MenuCategory[] {
  return categories
    .map((category) => ({
      ...category,
      items: category.items.filter((item) => item.isAvailable),
    }))
    .filter((category) => category.items.length > 0);
}

export function isHeaderIntegratedMenuCategoryNavMode(mode: MenuCategoryNavMode): boolean {
  return (
    mode === 'dock_in_header' ||
    mode === 'always_in_header' ||
    mode === 'compact_row'
  );
}

export function isInlineMenuCategoryNavMode(mode: MenuCategoryNavMode): boolean {
  return mode === 'sticky_strip' || mode === 'tabs_underline';
}

export function shouldObserveMenuCatalogForNav(mode: MenuCategoryNavMode): boolean {
  return mode === 'dock_in_header' || mode === 'compact_row';
}
