'use client';

import { useEffect, useRef, useState } from 'react';

const MENU_NAV_HEADER_OFFSET_PX = 72;

export function useMenuCatalogInView(enabled: boolean) {
  const anchorRef = useRef<HTMLDivElement>(null);
  const [menuNavActive, setMenuNavActive] = useState(false);

  useEffect(() => {
    if (!enabled) {
      setMenuNavActive(false);
      return;
    }

    const anchor = anchorRef.current;
    if (!anchor) {
      return;
    }

    const update = () => {
      const rect = anchor.getBoundingClientRect();
      setMenuNavActive(rect.top <= MENU_NAV_HEADER_OFFSET_PX);
    };

    update();

    const observer = new IntersectionObserver(
      () => {
        update();
      },
      {
        root: null,
        rootMargin: `-${MENU_NAV_HEADER_OFFSET_PX}px 0px 0px 0px`,
        threshold: [0, 0.01, 1],
      },
    );

    observer.observe(anchor);
    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);

    return () => {
      observer.disconnect();
      window.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
    };
  }, [enabled]);

  return { anchorRef, menuNavActive };
}
